mapper.select:
SELECT *, task_type_enum AS product_type FROM mes_building_task_order WHERE task_type_enum &


        #{productType}


        (16|32)

SELECT mto.id orderId, monomer.id 'monomer.id', monomer.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', a.production_line_id 'productionLine.id', cp.short_name 'project.shortName', cp.NAME 'project.name', cp.serial_number 'project.contractNo', cp.id 'project.id', mto.create_time scheduleTime, mto.order_number scheduleOrder, mto.ask_complete_time askCompleteTime, s.`name` userName, mto.task_type_enum productType, a.workshop_id 'workshop.id', a.workshop_name 'workshop.name', a.productionLine_name 'productionLine.name', mto.production_line_type_enum 'productionLine.productionLineTypeEnum', a.quantity taskQuantity, a.net_weight taskNetWeight, a.gross_weight taskGrossWeight, mto.print_quantity printQuantity FROM mes_building_task_order mto INNER JOIN ( SELECT a.task_order_id, a.workshop_id, a.workshop_name, a.production_line_id, a.productionLine_name, SUM(a.quantity) quantity, SUM(a.net_weight) net_weight, SUM(a.gross_weight) gross_weight FROM ( SELECT a.task_order_id, a.workshop_id, mw.`name` workshop_name, a.production_line_id, ml.`name` productionLine_name, SUM(a.task_quantity) quantity,
IFNULL( sum( a.task_quantity * ta.net_weight ), 0 ) net_weight, IFNULL( sum( a.task_quantity * ta.gross_weight ), 0 ) gross_weight
CASE a.task_type_enum WHEN 16 THEN IFNULL( sum( a.task_quantity * tb.net_weight ), 0 ) END net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( sum( a.task_quantity * tb.net_weight ), 0 ) END gross_weight
FROM mes_building_task a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id
LEFT JOIN tech_assemble tb ON tb.id = a.product_id
LEFT JOIN mes_building_workshop mw ON mw.id = a.workshop_id LEFT JOIN mes_building_production_line ml ON ml.id = a.production_line_id WHERE a.bool_delete_enum = 0
and a.create_time >= #{startDate}
and a.create_time <= #{endDate}
AND a.monomer_id in
#{monomerId}
AND a.task_type_enum = 2
AND a.area_id in
#{areaId}
AND a.area_batch_id in
#{areaBatchId}
and (
(a.product_id in
#{assembleId}
AND task_type_enum = 16 )
)
GROUP BY a.task_order_id, a.workshop_id, a.production_line_id, a.task_type_enum ) a GROUP BY a.task_order_id, a.workshop_id, a.workshop_name, a.production_line_id, a.productionLine_name ) a ON mto.id = a.task_order_id LEFT JOIN sys_user s ON mto.user_id = s.id LEFT JOIN contract_project cp ON cp.id = mto.project_id LEFT JOIN plan_monomer monomer ON mto.monomer_id = monomer.id LEFT JOIN plan_area area ON mto.area_id = area.id WHERE mto.bool_delete_enum = 0
and mto.project_id in
#{projectId}
AND mto.print_quantity > 0
AND mto.print_quantity = 0
AND a.workshop_id = #{workshopId}
and date_format(mto.create_time, '%Y-%m') = date_format(#{localDateTime}, '%Y-%m')
AND mto.order_number like concat('%', #{orderNumber}, '%')
AND mto.task_type_enum=#{taskType}
AND mto.id in ( SELECT a.task_order_id FROM mes_building_task a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id
LEFT JOIN tech_assemble ta ON ta.id = a.product_id
WHERE a.bool_delete_enum = 0
AND a.monomer_id in
#{monomerId}
AND a.task_type_enum = 2
AND a.area_id in
#{areaId}
AND a.area_batch_id in
#{areaBatchId}
AND a.task_type_enum & 16 and (
a.product_id in
#{assembleId}
)
AND ta.serial_number like CONCAT('%',#{serialNumber},'%') )
order by mto.create_time desc

SELECT mto.id orderId, a.production_line_id 'productionLine.id', cp.short_name 'project.shortName', cp.NAME 'project.name', cp.serial_number 'project.contractNo', cp.id 'project.id', monomer.id 'monomer.id', monomer.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', mto.create_time scheduleTime, mto.order_number scheduleOrder, mto.ask_complete_time askCompleteTime, s.`name` userName, mto.task_type_enum productType, a.workshop_id 'workshop.id', a.workshop_name 'workshop.name', a.productionLine_name 'productionLine.name', mto.production_line_type_enum 'productionLine.productionLineTypeEnum', a.quantity taskQuantity, a.net_weight taskNetWeight, a.gross_weight taskGrossWeight, mto.print_quantity printQuantity FROM mes_building_task_order mto INNER JOIN ( SELECT a.task_order_id, a.workshop_id, a.workshop_name, a.production_line_id, a.productionLine_name, SUM(a.quantity) quantity, SUM(a.net_weight) net_weight, SUM(a.gross_weight) gross_weight FROM ( SELECT a.task_order_id, a.workshop_id, mw.`name` workshop_name, a.production_line_id, ml.`name` productionLine_name, SUM(a.task_quantity) quantity, IFNULL( sum( a.task_quantity * ta.net_weight ), 0 ) net_weight, IFNULL( sum( a.task_quantity * ta.gross_weight ), 0 ) gross_weight FROM mes_building_task a LEFT JOIN tech_artifact ta ON ta.id = a.product_id LEFT JOIN mes_building_workshop mw ON mw.id = a.workshop_id LEFT JOIN mes_building_production_line ml ON ml.id = a.production_line_id WHERE a.bool_delete_enum = 0
and a.create_time >= #{startDate}
and a.create_time <= #{endDate}
AND ta.serial_number like CONCAT('%',#{serialNumber},'%')
AND a.monomer_id in
#{monomerId}
AND a.task_type_enum = 2
AND a.area_id in
#{areaId}
AND a.area_batch_id in
#{areaBatchId}
GROUP BY a.task_order_id, a.workshop_id, a.production_line_id, a.task_type_enum
union all SELECT a.task_order_id, a.workshop_id, mw.`name` workshop_name, a.production_line_id, ml.`name` productionLine_name, SUM(a.task_quantity) quantity, CASE a.task_type_enum WHEN 16 THEN IFNULL( sum( a.task_quantity * tb.net_weight ), 0 ) END net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( sum( a.task_quantity * tb.net_weight ), 0 ) END gross_weight FROM mes_building_task a LEFT JOIN tech_assemble tb ON tb.id = a.product_id LEFT JOIN mes_building_workshop mw ON mw.id = a.workshop_id LEFT JOIN mes_building_production_line ml ON ml.id = a.production_line_id WHERE a.bool_delete_enum = 0
and a.create_time >= #{startDate}
and a.create_time <= #{endDate}
AND tb.serial_number like CONCAT('%',#{serialNumber},'%')
AND a.monomer_id in
#{monomerId}
and (
(a.product_id in
#{assembleId}
AND task_type_enum = 16 )
) GROUP BY a.task_order_id, a.workshop_id, a.production_line_id, a.task_type_enum
) a GROUP BY a.task_order_id, a.workshop_id, a.workshop_name, a.production_line_id, a.productionLine_name ) a ON mto.id = a.task_order_id LEFT JOIN sys_user s ON mto.user_id = s.id LEFT JOIN contract_project cp ON cp.id = mto.project_id LEFT JOIN plan_monomer monomer ON mto.monomer_id = monomer.id LEFT JOIN plan_area area ON mto.area_id = area.id WHERE mto.bool_delete_enum = 0
and mto.project_id in
#{projectId}
AND mto.print_quantity != 0
AND mto.print_quantity = 0
AND a.workshop_id = #{workshopId}
and date_format(mto.create_time, '%Y-%m') = date_format(#{localDateTime}, '%Y-%m')
AND mto.order_number like concat('%', #{orderNumber}, '%')
order by mto.create_time desc

SELECT ta.serial_number serialNumber, ta.specification specification, ta.length length, ta.material material, task.task_quantity quantity, ta.net_weight weight FROM `mes_building_task` task LEFT JOIN tech_machine_part ta ON ta.id = task.product_id AND ta.bool_delete_enum = false WHERE task.bool_delete_enum = false
AND task.task_order_id = #{orderId}
AND task.task_type_enum =1

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.contractNo', ea.id 'areaId', ea.`name` 'areaName', mon.`name` monomer_name, par.monomer_id monomerId, par.serial_number 'serialNumber', par.specification 'specification', par.material 'material', par.id 'productId', ANY_VALUE(a.task_order_id) 'taskOrderId', IFNULL(SUM(a.task_quantity), 0) 'quantity', IFNULL(SUM(a.task_quantity*par.net_weight), 0) total_net_weight, IFNULL(SUM(a.task_quantity*par.gross_weight), 0) total_gross_weight, IFNULL(par.net_weight, 0) 'netWeight', IFNULL(par.gross_weight, 0) 'grossWeight' FROM mes_building_task_process a LEFT JOIN tech_machine_part par ON a.product_id = par.id LEFT JOIN contract_project cp ON par.project_id = cp.id LEFT JOIN plan_monomer mon ON mon.id = par.monomer_id LEFT JOIN plan_area ea on par.area_id = ea.id LEFT JOIN mes_building_process process ON a.process_id=process.id where a.bool_delete_enum=0
AND a.nest_cut_plate_id = #{cutId}
AND process.type = #{processType}
GROUP BY a.product_id ORDER BY par.id

SELECT t.id task_order_id, t.order_number, a.project_id 'project.id', cp.short_name 'project.shortName', cp.serial_number 'project.contractNo', cp.name 'project.name', a.workshop_id 'workshop.id', wp.name 'workshop.name', a.production_line_id 'productionLine.id', pl.name 'productionLine.name', a.groups_id 'groups.id', gr.name 'groups.name', t.create_time scheduleTime, t.task_type_enum productType, s.`name` userName , a.total_quantity, a. totalMete, a. total_net_weight, a.total_gross_weight, a. complete_quantity, a. completeMete, a.complete_net_weight, a. complete_gross_weight FROM( SELECT a.task_order_id task_order_id, a.project_id, a.workshop_id, a.production_line_id, a.groups_id, IFNULL( sum( a.task_quantity ), 0 ) total_quantity, IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) totalMete, IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) total_net_weight, IFNULL( SUM( a.task_quantity * ta.gross_weight ), 0 ) total_gross_weight, IFNULL( sum( a.complete_quantity ), 0 ) complete_quantity, IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) completeMete, IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( a.complete_quantity * ta.gross_weight ), 0 ) complete_gross_weight FROM `mes_building_task` a LEFT JOIN tech_machine_part ta ON a.product_id = ta.id
a.bool_delete_enum = FALSE AND a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@MACHINE_PART.getType()}
AND a.workshop_id = #{workshopId}
AND a.production_line_id = #{productionLineId}
AND a.product_id IN
#{partId}
GROUP BY a.task_order_id, a.project_id, a.workshop_id, a.production_line_id, a.groups_id)a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN mes_building_workshop wp ON wp.id = a.workshop_id LEFT JOIN mes_building_production_line pl ON pl.id = a.production_line_id LEFT JOIN mes_building_groups gr ON gr.id = a.groups_id LEFT JOIN mes_building_task_order t ON a.task_order_id = t.id LEFT JOIN sys_user s ON s.id = t.user_id
AND date_format( cp.create_time, '%Y' ) = date_format( #{dateTime}, '%Y' )
AND t.complete_time is NULL
AND t.complete_time is not NULL
AND t.order_number like concat('%',#{orderNumber},'%')

SELECT top_order.id task_order_id, top_order.order_number order_number, a.project_id 'project.id', a.short_name 'project.shortName', a.serial_number 'project.contractNo', a.project_name 'project.name', a.workshop_id 'workshop.id', a.workshop_name 'workshop.name', a.line_id 'productionLine.id', a.line_name 'productionLine.name', top_order.production_line_type_enum, top_order.create_time schedule_time, SUM(a.task_quantity) total_quantity, SUM(a.task_gross_weight) total_gross_weight, SUM(a.task_net_weight) total_net_weight, SUM(a.task_net_weight) total_mete, SUM(a.complete_quantity) complete_quantity, SUM(a.complete_net_weight) complete_net_weight, SUM(a.complete_net_weight) complete_mete, SUM(a.complete_gross_weight) complete_gross_weight FROM mes_building_top_task_order top_order INNER JOIN ( SELECT cp.id project_id, cp.`name`project_name, cp.short_name, cp.serial_number, wp.id workshop_id, wp.`name` workshop_name, pl.id line_id, pl.`name` line_name, a.top_task_order_id, a.complete_quantity, a.complete_net_weight, a.complete_gross_weight, a.task_quantity, a.task_net_weight, a.task_gross_weight FROM ( SELECT o.top_task_order_id, a.project_id, a.workshop_id, a.production_line_id, IFNULL( SUM( a.complete_quantity ), 0 ) complete_quantity, IFNULL( SUM( a.task_quantity ), 0 ) task_quantity, IFNULL( SUM( a.complete_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( a.complete_quantity * ta.gross_weight ), 0 ) complete_gross_weight, IFNULL( SUM( a.task_quantity * ta.net_weight ), 0 ) task_net_weight, IFNULL( SUM( a.task_quantity * ta.gross_weight ), 0 ) task_gross_weight FROM mes_building_task a LEFT JOIN mes_building_task_order o ON o.id = a.task_order_id LEFT JOIN tech_artifact ta ON ta.id = a.product_id WHERE a.bool_delete_enum = 0 AND a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
AND a.workshop_id = #{workshopId}
AND a.production_line_id = #{productionLineId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.project_id in
#{projectId}
GROUP BY o.top_task_order_id, a.workshop_id, a.project_id, a.production_line_id ) a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN mes_building_workshop wp ON wp.id = a.workshop_id LEFT JOIN mes_building_production_line pl ON pl.id = a.production_line_id
AND date_format( cp.create_time, '%Y' ) = date_format( #{dateTime}, '%Y' )
) a ON a.top_task_order_id = top_order.id
AND top_order.complete_time is null
AND top_order.complete_time is not null
AND top_order.order_number like concat('%',#{orderNumber},'%')
GROUP BY top_order.id,a.workshop_id,a.line_id,top_order.create_time,a.project_id

SELECT DISTINCT par.id FROM mes_building_nest_cut_machine_part_separate a LEFT JOIN tech_machine_part par ON a.product_id = par.id LEFT JOIN contract_project cp ON par.project_id = cp.id LEFT JOIN plan_monomer mon ON mon.id = par.monomer_id where 1=1
AND a.nest_cut_id = #{cutId}
AND a.process_type = #{processType}
GROUP BY a.product_id order BY par.id DESC

select count(*)
from mes_building_task_order


        AND task_type_enum = #{taskTypeEnum}


        AND top_task_order_id = #{topTaskOrderId}

SELECT ANY_VALUE(a.id) id, ANY_VALUE(a.part_id) part_id, ANY_VALUE(a.bool_complete_enum) bool_complete_enum, ANY_VALUE(a.label_status) label_status, ANY_VALUE(par.thick) thick, ANY_VALUE(cp.id) 'project.id', ANY_VALUE(cp.NAME) 'project.name', ANY_VALUE(cp.short_name) 'project.shortName', ANY_VALUE(cp.serial_number) 'project.contractNo', ANY_VALUE(ea.id) 'areaId', ANY_VALUE(ea.`name`) 'areaName', ANY_VALUE(par.monomer_id) monomerId, ANY_VALUE(par.serial_number) 'serialNumber', ANY_VALUE(par.specification) 'specification', ANY_VALUE(par.material) 'material', ANY_VALUE(par.id) 'productId', IFNULL(SUM(a.quantity ), 0 ) 'quantity', IFNULL(SUM(taskProcess.complete_quantity), 0) 'complete_quantity', IFNULL(SUM(taskProcess.complete_quantity * par.net_weight), 0) 'complete_net_weight', IFNULL(SUM(a.quantity*par.net_weight), 0) total_net_weight, IFNULL(SUM(a.quantity*par.gross_weight), 0) total_gross_weight, ANY_VALUE(IFNULL( par.net_weight, 0 )) 'netWeight', ANY_VALUE(IFNULL( par.gross_weight, 0 )) 'grossWeight' FROM mes_building_nest_cut_plate_part a LEFT JOIN tech_machine_part par ON a.part_id = par.id LEFT JOIN contract_project cp ON par.project_id = cp.id LEFT JOIN plan_monomer mon ON mon.id = par.monomer_id LEFT JOIN plan_area ea on par.area_id = ea.id LEFT JOIN mes_building_task_process taskProcess ON par.id = taskProcess.product_id AND taskProcess.task_type_enum = 1 AND taskProcess.sequence = 1 AND taskProcess.bool_delete_enum = 0 AND a.mes_building_nest_cut_plate_id = taskProcess.nest_cut_plate_id WHERE a.bool_delete_enum = 0 AND taskProcess.id is not null
AND a.mes_building_nest_cut_plate_id = #{cutId}
GROUP BY a.part_id ORDER BY par.id

SELECT ANY_VALUE(a.id) id, ANY_VALUE(a.part_id) part_id, ANY_VALUE(a.bool_complete_enum) bool_complete_enum, ANY_VALUE(a.label_status) label_status, ANY_VALUE(par.thick) thick, ANY_VALUE(cp.id) 'project.id', ANY_VALUE(cp.NAME) 'project.name', ANY_VALUE(cp.short_name) 'project.shortName', ANY_VALUE(cp.serial_number) 'project.contractNo', ANY_VALUE(ea.id) 'areaId', ANY_VALUE(ea.`name`) 'areaName', ANY_VALUE(par.monomer_id) monomerId, ANY_VALUE(par.serial_number) 'serialNumber', ANY_VALUE(par.specification) 'specification', ANY_VALUE(par.material) 'material', ANY_VALUE(par.id) 'productId', IFNULL(SUM(taskProcess.task_quantity ), 0 ) 'quantity', IFNULL(SUM(taskProcess.complete_quantity), 0) 'complete_quantity', IFNULL(SUM(taskProcess.complete_quantity * par.net_weight), 0) 'complete_net_weight', IFNULL(SUM(taskProcess.task_quantity*par.net_weight), 0) total_net_weight, IFNULL(SUM(taskProcess.task_quantity*par.gross_weight), 0) total_gross_weight, ANY_VALUE(IFNULL( par.net_weight, 0 )) 'netWeight', ANY_VALUE(IFNULL( par.gross_weight, 0 )) 'grossWeight', par.length FROM mes_building_nest_cut_plate_part a LEFT JOIN tech_machine_part par ON a.part_id = par.id LEFT JOIN contract_project cp ON par.project_id = cp.id LEFT JOIN plan_monomer mon ON mon.id = par.monomer_id LEFT JOIN plan_area ea on par.area_id = ea.id LEFT JOIN mes_building_task_process taskProcess ON par.id = taskProcess.product_id AND taskProcess.task_type_enum = 1 AND taskProcess.sequence = 1 AND taskProcess.bool_delete_enum = 0 AND a.mes_building_nest_cut_plate_id = taskProcess.nest_cut_plate_id WHERE a.bool_delete_enum = 0 AND taskProcess.id is not null
AND a.mes_building_nest_cut_plate_id = #{cutId} AND taskProcess.nest_cut_plate_id = #{cutId}
AND par.monomer_id = #{monomerId}
AND par.area_id = #{areaId}
GROUP BY a.part_id ORDER BY par.id

SELECT ANY_VALUE(a.id) id, ANY_VALUE(a.part_id) part_id, ANY_VALUE(a.bool_complete_enum) bool_complete_enum, ANY_VALUE(a.label_status) label_status, ANY_VALUE(par.thick) thick, ANY_VALUE(cp.id) 'project.id', ANY_VALUE(cp.NAME) 'project.name', ANY_VALUE(cp.short_name) 'project.shortName', ANY_VALUE(cp.serial_number) 'project.contractNo', ANY_VALUE(ea.id) 'areaId', ANY_VALUE(ea.`name`) 'areaName', ANY_VALUE(par.monomer_id) monomerId, ANY_VALUE(par.serial_number) 'serialNumber', ANY_VALUE(par.specification) 'specification', ANY_VALUE(par.material) 'material', ANY_VALUE(par.id) 'productId', IFNULL( SUM( a.quantity ), 0 ) 'quantity', IFNULL(SUM(a.complete_quantity), 0) 'complete_quantity', IFNULL(SUM(a.quantity*par.net_weight), 0) total_net_weight, IFNULL(SUM(a.quantity*par.gross_weight), 0) total_gross_weight, ANY_VALUE(IFNULL( par.net_weight, 0 )) 'netWeight', ANY_VALUE(IFNULL( par.gross_weight, 0 )) 'grossWeight', par.length FROM mes_building_nest_cut_plate_part a LEFT JOIN tech_machine_part par ON a.part_id = par.id LEFT JOIN contract_project cp ON par.project_id = cp.id LEFT JOIN plan_monomer mon ON mon.id = par.monomer_id LEFT JOIN plan_area ea on par.area_id = ea.id LEFT JOIN mes_building_task_process taskProcess ON par.id = taskProcess.product_id AND taskProcess.task_type_enum = 1 AND taskProcess.sequence = 0 AND taskProcess.bool_delete_enum = 0 AND a.mes_building_nest_cut_plate_id = taskProcess.nest_cut_plate_id WHERE a.bool_delete_enum = 0 AND taskProcess.id is not null
AND a.mes_building_nest_cut_plate_id = #{cutId}
AND par.monomer_id = #{monomerId}
AND par.area_id = #{areaId}
GROUP BY a.part_id ORDER BY par.id

SELECT cp.short_name as shortName, cp.NAME as name, cp.serial_number as serialNumber, cp.project_type as projectType, cp.id as id FROM mes_building_task_order mto LEFT JOIN contract_project cp ON cp.id = mto.project_id LEFT JOIN mes_building_production_line ml ON ml.id = mto.production_line_id WHERE mto.bool_delete_enum = 0
and mto.project_id in
#{projectId}
AND ml.workshop_id = #{workshopId}
and date_format(mto.create_time, '%Y-%m') = date_format(#{monthDate}, '%Y-%m')
AND (mto.task_type_enum = 2 or mto.task_type_enum = 16) group by mto.project_id
